final class MessageArchiveRequestClassificationTests: XCTestCase {

    private let owner = "owner@example.com"
    private let jid = "romeo@example.com"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "MessageArchiveRequestClassificationTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    private func queuedTask(
        _ manager: MessageArchiveManager,
        queryId: String
    ) -> MessageArchiveManager.MAMRequestItem? {
        manager.callbacksQueue.first(where: { $0.elementId == queryId })?.task
    }

    private func insertAccount(createdAt: Date) throws {
        let realm = try WRealm.safe()
        let account = AccountStorageItem()
        account.jid = owner
        account.createdAt = createdAt

        try realm.write {
            realm.add(account, update: .modified)
        }
    }

    private func assertDate(
        _ actual: Date?,
        equals expected: Date,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        guard let actual = actual else {
            XCTFail("Expected date \(expected), got nil", file: file, line: line)
            return
        }
        XCTAssertEqual(actual.timeIntervalSince1970, expected.timeIntervalSince1970, accuracy: 0.001, file: file, line: line)
    }

    func testBootstrapPurposeMarksInitialArchiveLoaded() {
        XCTAssertTrue(MessageArchiveManager.RequestPurpose.bootstrap.marksInitialArchiveLoaded)
    }

    func testNonBootstrapPurposesDoNotMarkInitialArchiveLoaded() {
        let purposes: [MessageArchiveManager.RequestPurpose] = [
            .pageOlder,
            .pageNewer,
            .jump,
            .gapRepair,
            .snapshotRepair,
            .search,
            .latest,
            .media
        ]

        XCTAssertTrue(purposes.allSatisfy { !$0.marksInitialArchiveLoaded })
    }

    func testArchiveProducingPurposesAreClassifiedExplicitly() {
        let archiveProducing: [MessageArchiveManager.RequestPurpose] = [
            .bootstrap,
            .pageOlder,
            .pageNewer,
            .jump,
            .gapRepair,
            .snapshotRepair
        ]
        let nonArchiveProducing: [MessageArchiveManager.RequestPurpose] = [
            .search,
            .latest,
            .media
        ]

        XCTAssertTrue(archiveProducing.allSatisfy(\.isArchiveHistoryProducing))
        XCTAssertTrue(nonArchiveProducing.allSatisfy { !$0.isArchiveHistoryProducing })
    }

    func testRegularHistoryRequestsOmitConversationTypeFilter() {
        XCTAssertFalse(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .regular,
                purpose: .bootstrap,
                isGroupchat: false,
                isExtendedArchiveAvailable: true
            )
        )

        XCTAssertFalse(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .regular,
                purpose: .pageOlder,
                isGroupchat: false,
                isExtendedArchiveAvailable: true
            )
        )
    }

    func testRegularSnapshotRepairPreservesConversationTypeFilterWhenExtensionIsAvailable() {
        XCTAssertTrue(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .regular,
                purpose: .snapshotRepair,
                isGroupchat: false,
                isExtendedArchiveAvailable: true
            )
        )
    }

    func testNonRegularDirectHistoryUsesConversationTypeOnlyWithArchiveExtension() {
        XCTAssertTrue(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .omemo,
                purpose: .bootstrap,
                isGroupchat: false,
                isExtendedArchiveAvailable: true
            )
        )

        XCTAssertFalse(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .omemo,
                purpose: .bootstrap,
                isGroupchat: false,
                isExtendedArchiveAvailable: false
            )
        )
    }

    func testGroupHistoryRequestsOmitConversationTypeFilter() {
        XCTAssertFalse(
            MessageArchiveManager.ConversationTypeFilterPolicy.shouldIncludeConversationTypeField(
                conversationType: .group,
                purpose: .bootstrap,
                isGroupchat: true,
                isExtendedArchiveAvailable: true
            )
        )
    }

    func testInitialBootstrapPolicyStartsForEmptyUnconfirmedOrUnsyncedChatsOnly() {
        XCTAssertTrue(
            MessageArchiveManager.ChatBootstrapRequestPolicy.shouldStartInitialBootstrap(
                isSynced: true,
                isInitialArchiveLoaded: false,
                localMessageCount: 0
            )
        )
        XCTAssertTrue(
            MessageArchiveManager.ChatBootstrapRequestPolicy.shouldStartInitialBootstrap(
                isSynced: false,
                isInitialArchiveLoaded: true,
                localMessageCount: 3
            )
        )
        XCTAssertFalse(
            MessageArchiveManager.ChatBootstrapRequestPolicy.shouldStartInitialBootstrap(
                isSynced: true,
                isInitialArchiveLoaded: true,
                localMessageCount: 0
            )
        )
        XCTAssertFalse(
            MessageArchiveManager.ChatBootstrapRequestPolicy.shouldStartInitialBootstrap(
                isSynced: true,
                isInitialArchiveLoaded: true,
                localMessageCount: 3
            )
        )
    }

    func testPersistedOlderCursorUsesOldestRsmBoundaryForBootstrap() {
        XCTAssertEqual(
            MessageArchiveManager.HistoryCursorPolicy.persistedOlderCursorId(
                purpose: .bootstrap,
                first: "newest-page-boundary",
                last: "oldest-archived-id",
                current: "existing-cursor"
            ),
            "oldest-archived-id"
        )
    }

    func testPersistedOlderCursorUsesOldestRsmBoundaryForOlderPaging() {
        XCTAssertEqual(
            MessageArchiveManager.HistoryCursorPolicy.persistedOlderCursorId(
                purpose: .pageOlder,
                first: "newest-page-boundary",
                last: "older-boundary",
                current: "existing-cursor"
            ),
