    func testRegularGapRepairOlderPlanUsesNewerGapBoundaryAsBeforeCursor() {
        let gap = RegularChatArchiveGap(
            olderRangeNewestArchiveId: "200",
            newerRangeOldestArchiveId: "400"
        )
        let plan = MessageArchiveManager.regularGapRepairRequestPlan(
            jid: "romeo@example.com",
            gap: gap,
            direction: .older,
            pageSize: 100
        )

        XCTAssertEqual(plan.kind, .gapRepair)
        XCTAssertEqual(plan.purpose, .gapRepair)
        XCTAssertEqual(plan.nextPage, "400")
        XCTAssertNil(plan.prevPage)
        XCTAssertTrue(plan.usesServerArchiveId)
    }

    func testRegularGapRepairNewerPlanUsesOlderGapBoundaryAsAfterCursor() {
        let gap = RegularChatArchiveGap(
            olderRangeNewestArchiveId: "200",
            newerRangeOldestArchiveId: "400"
        )
        let plan = MessageArchiveManager.regularGapRepairRequestPlan(
            jid: "romeo@example.com",
            gap: gap,
            direction: .newer,
            pageSize: 100
        )

        XCTAssertEqual(plan.kind, .gapRepair)
        XCTAssertEqual(plan.purpose, .gapRepair)
        XCTAssertNil(plan.nextPage)
        XCTAssertEqual(plan.prevPage, "200")
        XCTAssertTrue(plan.usesServerArchiveId)
    }
}

final class RegularChatArchiveSyncStateTests: XCTestCase {

    private let owner = "juliet@example.com"
    private let jid = "romeo@example.com"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "RegularChatArchiveSyncStateTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    func testMergingRegularArchivePageUpdatesBoundsAndContinuousRange() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "300", last: "200", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "250", last: "100", updateKind: .disjointWindow)
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(state.oldestLoadedArchiveId, "100")
        XCTAssertEqual(state.newestLoadedArchiveId, "300")
        XCTAssertEqual(state.loadedRanges, [RegularChatArchiveIDRange(oldestArchiveId: "100", newestArchiveId: "300")])
        XCTAssertTrue(state.knownGaps.isEmpty)
    }

    func testDisjointRegularArchiveRangesRecordKnownGap() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "200", last: "100", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "500", last: "400", updateKind: .disjointWindow)
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(
            state.knownGaps,
            [RegularChatArchiveGap(olderRangeNewestArchiveId: "200", newerRangeOldestArchiveId: "400")]
        )
    }

    func testOlderExclusiveRsmPageMergesByRequestAdjacency() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "500", last: "400", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "399", last: "300", updateKind: .pageOlder(cursorArchiveId: "400"))
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(state.loadedRanges, [RegularChatArchiveIDRange(oldestArchiveId: "300", newestArchiveId: "500")])
        XCTAssertTrue(state.knownGaps.isEmpty)
    }

    func testNewerExclusiveRsmPageMergesByRequestAdjacency() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "200", last: "100", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "300", last: "201", updateKind: .pageNewer(cursorArchiveId: "200"))
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(state.loadedRanges, [RegularChatArchiveIDRange(oldestArchiveId: "100", newestArchiveId: "300")])
        XCTAssertTrue(state.knownGaps.isEmpty)
    }

    func testPartialGapRepairShrinksKnownGap() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "200", last: "100", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "500", last: "400", updateKind: .disjointWindow)
            state.mergeLoadedRange(first: "399", last: "300", updateKind: .gapRepairOlder(cursorArchiveId: "400"))
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(
            state.loadedRanges,
            [
                RegularChatArchiveIDRange(oldestArchiveId: "100", newestArchiveId: "200"),
                RegularChatArchiveIDRange(oldestArchiveId: "300", newestArchiveId: "500")
            ]
        )
        XCTAssertEqual(
            state.knownGaps,
            [RegularChatArchiveGap(olderRangeNewestArchiveId: "200", newerRangeOldestArchiveId: "300")]
        )
    }

    func testGapRepairPageThatReachesOlderRangeRemovesKnownGap() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "200", last: "100", updateKind: .bootstrapNewest)
            state.mergeLoadedRange(first: "500", last: "400", updateKind: .disjointWindow)
            state.mergeLoadedRange(first: "399", last: "150", updateKind: .gapRepairOlder(cursorArchiveId: "400"))
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertEqual(state.loadedRanges, [RegularChatArchiveIDRange(oldestArchiveId: "100", newestArchiveId: "500")])
        XCTAssertTrue(state.knownGaps.isEmpty)
    }

    func testSnapshotIdentityDoesNotCreateKnownGapWithoutLoadedNewerWindow() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let state = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, in: realm)
            state.mergeLoadedRange(first: "200", last: "100", updateKind: .bootstrapNewest)
            state.recordKnownNewerGap(to: "500")
        }

        let state = try XCTUnwrap(realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner)
        ))
        XCTAssertTrue(state.knownGaps.isEmpty)
    }

    func testArchiveStatePrimaryIncludesConversationType() throws {
        let realm = try WRealm.safe()
        try realm.write {
            _ = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, conversationType: .regular, in: realm)
            _ = RegularChatArchiveSyncStateStorageItem.ensure(owner: owner, jid: jid, conversationType: .group, in: realm)
        }

        let regular = realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner, conversationType: .regular)
        )
        let group = realm.object(
            ofType: RegularChatArchiveSyncStateStorageItem.self,
            forPrimaryKey: RegularChatArchiveSyncStateStorageItem.genPrimary(jid: jid, owner: owner, conversationType: .group)
        )

        XCTAssertNotNil(regular)
        XCTAssertNotNil(group)
        XCTAssertNotEqual(regular?.primary, group?.primary)
        XCTAssertEqual(group?.conversationType, .group)
    }
}

final class MessageArchiveQueryCallbackTests: XCTestCase {

    private let owner = "owner@example.com"

    override func setUp() {
        super.setUp()
        MessageArchiveEndPageDispatcher.resetForTests()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "MessageArchiveQueryCallbackTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        MessageArchiveEndPageDispatcher.resetForTests()
        super.tearDown()
    }

    private func makeElement(xml: String) throws -> DDXMLElement {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "MessageArchiveQueryCallbackTests", code: 1)
        }
        return root
    }

    private func makeIQ(xml: String) throws -> XMPPIQ {
        XMPPIQ(from: try makeElement(xml: xml))
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        XMPPMessage(from: try makeElement(xml: xml))
    }

    private func insertLastChat(
        jid: String = "romeo@example.com",
        conversationType: ClientSynchronizationManager.ConversationType = .regular,
        fullArchiveLoaded: Bool = false,
        lastLoadedMessageHistoryId: String? = nil
    ) throws {
        let realm = try WRealm.safe()
        let chat = LastChatsStorageItem()
        chat.jid = jid
        chat.conversationType = conversationType
        chat.primary = LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: conversationType)
        chat.owner = owner
        chat.fullArchiveLoaded = fullArchiveLoaded
        chat.lastLoadedMessageHistoryId = lastLoadedMessageHistoryId

        try realm.write {
            realm.add(chat, update: .modified)
        }
    }

    private func fullArchiveLoaded(
        jid: String = "romeo@example.com",
        conversationType: ClientSynchronizationManager.ConversationType = .regular
    ) throws -> Bool {
        let realm = try WRealm.safe()
        return realm.object(
            ofType: LastChatsStorageItem.self,
            forPrimaryKey: LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: conversationType)
        )?.fullArchiveLoaded ?? false
    }

    private func persistedHistoryCursorId(
        jid: String = "romeo@example.com",
        conversationType: ClientSynchronizationManager.ConversationType = .regular
    ) throws -> String? {
        let realm = try WRealm.safe()
        return realm.object(
            ofType: LastChatsStorageItem.self,
            forPrimaryKey: LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: conversationType)
        )?.lastLoadedMessageHistoryId
    }

    private func queuedTask(
        _ manager: MessageArchiveManager,
        queryId: String
    ) -> MessageArchiveManager.MAMRequestItem? {
        manager.callbacksQueue.first(where: { $0.elementId == queryId })?.task
    }

    private func makeEndPageEvent(
        queryId: String = "MAM next history: dispatcher",
        source: MessageArchiveEndPageEvent.Source = .localCallback
    ) -> MessageArchiveEndPageEvent {
        MessageArchiveEndPageEvent(
            owner: owner,
            queryId: queryId,
            state: MessageArchivePageEndState(
                queryExhausted: false,
                archiveEnded: false,
                persistedMessageCount: 0,
                requestCursorId: nil
            ),
            first: "1616150755947399",
            last: "1615552290910923",
            count: 101,
            streamKind: .uiAction,
            source: source
        )
    }

    func testEndPageDispatcherDeliversMatchingQueryOnce() {
        let queryId = "MAM next history: dispatcher-once"
        let callbackExpectation = expectation(description: "dispatcher callback")
        callbackExpectation.assertForOverFulfill = true
        var receivedEvents: [MessageArchiveEndPageEvent] = []

        MessageArchiveEndPageDispatcher.register(owner: owner, queryId: queryId) { event in
            XCTAssertTrue(Thread.isMainThread)
            receivedEvents.append(event)
            callbackExpectation.fulfill()
        }

        XCTAssertTrue(MessageArchiveEndPageDispatcher.publish(makeEndPageEvent(queryId: queryId)))
        XCTAssertFalse(MessageArchiveEndPageDispatcher.publish(makeEndPageEvent(queryId: queryId, source: .fallbackCallback)))

        wait(for: [callbackExpectation], timeout: 1.0)
        XCTAssertEqual(receivedEvents.count, 1)
        XCTAssertEqual(receivedEvents.first?.queryId, queryId)
    }

    func testEndPageDispatcherUnregisterPreventsStaleDelivery() {
        let queryId = "MAM next history: dispatcher-unregister"
        let unexpectedExpectation = expectation(description: "dispatcher callback should not fire")
        unexpectedExpectation.isInverted = true

        let token = MessageArchiveEndPageDispatcher.register(owner: owner, queryId: queryId) { _ in
            unexpectedExpectation.fulfill()
        }
        MessageArchiveEndPageDispatcher.unregister(token)

        XCTAssertFalse(MessageArchiveEndPageDispatcher.publish(makeEndPageEvent(queryId: queryId)))
        wait(for: [unexpectedExpectation], timeout: 0.2)
    }

    func testArchiveRequestRegistersCallbackBeforeSendingStanza() {
        let manager = MessageArchiveManager(withOwner: owner)
        let stream = CapturingXMPPStream()
        let queryId = "MAM race: callback-before-send"
        var callbackRegisteredAtSend = false
        var queryRegisteredAtSend = false
        var archivePurposeRegisteredAtSend = false

        stream.onSendElement = { _ in
            callbackRegisteredAtSend = manager.callbacksQueue.contains { $0.elementId == queryId }
            queryRegisteredAtSend = manager.queryIds.contains(queryId)
            archivePurposeRegisteredAtSend = manager.shouldPersistArchiveQueryId(queryId)
        }

        manager.getNextHistory(
            stream,
            for: "romeo@example.com",
            conversationType: .saved,
            messageId: "cursor-1",
            pageSize: 100,
            queryId: queryId
        )

        XCTAssertTrue(callbackRegisteredAtSend)
        XCTAssertTrue(queryRegisteredAtSend)
        XCTAssertTrue(archivePurposeRegisteredAtSend)
    }

    func testFinalIQUsesRegisteredFallbackCallbackWhenLocalCallbackItemIsMissing() throws {
        let requestManager = MessageArchiveManager(withOwner: owner)
        let receiverManager = MessageArchiveManager(withOwner: owner)
        let stream = CapturingXMPPStream()
        let queryId = "MAM next history: orphan-final"
        var receivedQueryId: String?
        var receivedState: MessageArchivePageEndState?
        var receivedFirst: String?
        var receivedLast: String?
        var receivedCount: Int?
        let callbackExpectation = expectation(description: "orphan final iq callback")

        requestManager.getNextHistory(
            stream,
            for: "romeo@example.com",
            conversationType: .regular,
            messageId: "500",
            pageSize: 100,
            queryId: queryId,
            requestCallbacks: .init(
                onMessage: nil,
                onEndPage: { queryId, state, first, last, count in
                    receivedQueryId = queryId
                    receivedState = state
                    receivedFirst = first
                    receivedLast = last
                    receivedCount = count
                    callbackExpectation.fulfill()
                }
            ),
            deferCoverageCommitUntilConsumerProof: true
        )
        requestManager.didResetState()

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <fin xmlns='urn:xmpp:mam:2' complete='false' queryid='\(queryId)'>
            <set xmlns='http://jabber.org/protocol/rsm'>
              <count>101</count>
              <first>1616150755947399</first>
              <last>1615552290910923</last>
            </set>
          </fin>
        </iq>
        """)

        XCTAssertTrue(receiverManager.read(stream, withIQ: iq))
        wait(for: [callbackExpectation], timeout: 1.0)
        XCTAssertEqual(receivedQueryId, queryId)
        XCTAssertEqual(
            receivedState,
            .init(
                queryExhausted: false,
                archiveEnded: false,
                persistedMessageCount: 0,
                requestCursorId: nil
            )
        )
        XCTAssertEqual(receivedFirst, "1616150755947399")
        XCTAssertEqual(receivedLast, "1615552290910923")
        XCTAssertEqual(receivedCount, 101)
    }

