        XCTAssertTrue(controller.datasource.isEmpty)
        XCTAssertEqual(controller.tableView.numberOfRows(inSection: 0), 0)
    }

    func testLastChatsViewControllerUnreadFilterUsesMirroredUnreadTotal() throws {
