    func testRecordingPulseMeteringAnimatesClampedColoredShadow() {
        let inputView = ModernXabberInputView(frame: CGRect(
            x: 0,
            y: 0,
            width: 390,
            height: ModernXabberInputView.defaultBarHeight
        ))
        inputView.changeState(to: .record)
