    private func composerEffectView(containing view: UIView) -> UIVisualEffectView? {
        var currentSuperview = view.superview
        while let current = currentSuperview {
            if let effectView = current as? UIVisualEffectView {
                return effectView
            }
            currentSuperview = current.superview
        }
        return nil
    }

    private func detachedButtonEffectView(in button: UIButton) -> UIVisualEffectView? {
        button.subviews.compactMap { $0 as? UIVisualEffectView }.first
    }

    private func isDetachedButtonChromeHidden(_ button: UIButton) -> Bool {
        if #available(iOS 26.0, *) {
            return button.configuration == nil
        }
        return detachedButtonEffectView(in: button)?.isHidden ?? true
    }

    private func visualEffectViewCount(in view: UIView) -> Int {
        view.subviews.reduce(view is UIVisualEffectView ? 1 : 0) { count, subview in
            count + visualEffectViewCount(in: subview)
        }
    }

    private func visibleRootImageViewCount(in view: UIView) -> Int {
        view.subviews.compactMap { $0 as? UIImageView }.filter { imageView in
            !imageView.isHidden && imageView.alpha > 0.01
        }.count
    }

    private func descendantCount(in view: UIView, where predicate: (UIView) -> Bool) -> Int {
        view.subviews.reduce(predicate(view) ? 1 : 0) { count, subview in
            count + descendantCount(in: subview, where: predicate)
        }
    }

    private func assertContextPreviewAccentFollowsIcon(
        _ panel: ModernXabberInputView.ComposerContextPreviewView,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        let iconFrame = panel.indicatorButton.convert(panel.indicatorButton.bounds, to: panel)
        let accentFrame = panel.accentView.convert(panel.accentView.bounds, to: panel)
        let labelsFrame = panel.labelsStack.convert(panel.labelsStack.bounds, to: panel)

        XCTAssertEqual(accentFrame.width, 1, accuracy: 0.001, file: file, line: line)
        XCTAssertLessThan(iconFrame.maxX, accentFrame.minX, file: file, line: line)
        XCTAssertLessThan(accentFrame.maxX, labelsFrame.minX, file: file, line: line)
    }

    private func assertPlayerBarIconOnlyStyle(
        _ button: UIButton,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertNil(button.configuration, file: file, line: line)
        XCTAssertEqual(button.backgroundColor ?? .clear, .clear, file: file, line: line)
        XCTAssertEqual(button.tintColor, AudioPlayerBarIconButtonStyle.tintColor, file: file, line: line)
        XCTAssertEqual(button.bounds.width, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001, file: file, line: line)
        XCTAssertEqual(button.bounds.height, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001, file: file, line: line)
        XCTAssertEqual(button.contentHorizontalAlignment, .center, file: file, line: line)
        XCTAssertEqual(button.contentVerticalAlignment, .center, file: file, line: line)
        XCTAssertTrue(button.adjustsImageWhenHighlighted, file: file, line: line)
        XCTAssertTrue(button.adjustsImageWhenDisabled, file: file, line: line)
    }
}

private extension UIView {
    func containsDescendant<T: UIView>(ofType type: T.Type) -> Bool {
        for subview in subviews {
            if subview is T || subview.containsDescendant(ofType: type) {
                return true
            }
        }
        return false
    }

    func hasClippingAncestor(stoppingAt stopView: UIView) -> Bool {
        var currentSuperview = superview
        while let current = currentSuperview, current !== stopView {
            if current.clipsToBounds || current.layer.masksToBounds {
                return true
            }
            currentSuperview = current.superview
        }
        return false
    }
}

final class ChatInitialMessageOverlayLayoutTests: XCTestCase {

    private let viewBounds = CGRect(x: 0, y: 0, width: 390, height: 844)
    private let safeAreaInsets = UIEdgeInsets(top: 47, left: 0, bottom: 34, right: 0)

    func testOverlayFrameIsCenteredWhenKeyboardIsHiddenAndSpaceIsSufficient() {
        let frame = ChatViewController.InitialMessageOverlayLayoutPolicy.frame(
            viewBounds: viewBounds,
            safeAreaInsets: safeAreaInsets,
            inputTopY: 761
        )

        XCTAssertEqual(frame.width, 340, accuracy: 0.001)
        XCTAssertEqual(frame.height, 340, accuracy: 0.001)
        XCTAssertEqual(frame.midX, viewBounds.midX, accuracy: 0.001)
        XCTAssertEqual(frame.midY, 404, accuracy: 0.001)
        XCTAssertLessThanOrEqual(frame.maxY, 761)
    }

    func testOverlayFrameStaysAboveComposerWhenKeyboardIsVisible() {
        let inputTopY: CGFloat = 461
        let frame = ChatViewController.InitialMessageOverlayLayoutPolicy.frame(
            viewBounds: viewBounds,
            safeAreaInsets: safeAreaInsets,
            inputTopY: inputTopY
        )

        XCTAssertEqual(frame.height, 340, accuracy: 0.001)
        XCTAssertLessThan(frame.midY, viewBounds.midY)
        XCTAssertLessThanOrEqual(frame.maxY, inputTopY - 12 + 0.001)
    }

    func testOverlayFrameShrinksInsideConstrainedVisibleHeight() {
        let inputTopY: CGFloat = 170
        let frame = ChatViewController.InitialMessageOverlayLayoutPolicy.frame(
            viewBounds: viewBounds,
            safeAreaInsets: safeAreaInsets,
            inputTopY: inputTopY
        )

        XCTAssertGreaterThan(frame.height, 0)
        XCTAssertLessThan(frame.height, 340)
        XCTAssertLessThanOrEqual(frame.maxY, inputTopY - 12 + 0.001)
    }

    func testInitialMessageOverlayContentsStayInsideShrunkOuterFrame() {
        let overlayView = ChatViewController.InitialMessageOverlayView(frame: .zero)
        overlayView.update(
            frame: CGRect(x: 0, y: 0, width: 340, height: 120),
            conversationType: .regular
        )

        XCTAssertGreaterThanOrEqual(overlayView.iconButton.frame.minY, 0)
        XCTAssertLessThanOrEqual(overlayView.iconButton.frame.maxY, overlayView.bounds.maxY + 0.001)
        XCTAssertGreaterThanOrEqual(overlayView.containerView.frame.minY, 0)
        XCTAssertLessThanOrEqual(overlayView.containerView.frame.maxY, overlayView.bounds.maxY + 0.001)
    }

    func testKeyboardOverlapHeightHandlesHiddenVisibleAndPartialFrames() {
        XCTAssertEqual(
            ChatViewController.keyboardOverlapHeight(
                viewBounds: viewBounds,
                keyboardFrameInView: CGRect(x: 0, y: 544, width: 390, height: 300)
            ),
            300,
            accuracy: 0.001
        )
        XCTAssertEqual(
            ChatViewController.keyboardOverlapHeight(
                viewBounds: viewBounds,
                keyboardFrameInView: CGRect(x: 0, y: 844, width: 390, height: 300)
            ),
            0,
            accuracy: 0.001
        )
        XCTAssertEqual(
            ChatViewController.keyboardOverlapHeight(
                viewBounds: viewBounds,
                keyboardFrameInView: CGRect(x: 0, y: 760, width: 390, height: 300)
            ),
            84,
            accuracy: 0.001
        )
    }
}

final class ChatScrollDownButtonPolicyTests: XCTestCase {

    private func chatState(
        unread: Int = 1,
        syncUnreadAfterId: String? = "300",
        lastReadId: String? = nil
    ) -> ChatScrollDownTargetPolicy.ChatState {
        ChatScrollDownTargetPolicy.ChatState(
            unread: unread,
            syncUnreadAfterId: syncUnreadAfterId,
            lastReadId: lastReadId
        )
    }

    private func visibleMessage(
        archivedId: String?,
        rowKind: ChatVisiblePositionPolicy.RowKind = .message,
        isFakeMessage: Bool = false
    ) -> ChatScrollDownTargetPolicy.VisibleMessage {
        ChatScrollDownTargetPolicy.VisibleMessage(
            archivedId: archivedId,
            rowKind: rowKind,
            isFakeMessage: isFakeMessage
        )
    }

    func testVisibilityPolicyShowsOnlyBeyondFortyFourWhenNotNearBottomOrSearch() {
        XCTAssertFalse(
            ChatScrollDownButtonVisibilityPolicy.shouldShow(
                contentOffsetY: 43.99,
                isNearBottom: false,
                isSearchMode: false
            )
        )
        XCTAssertFalse(
            ChatScrollDownButtonVisibilityPolicy.shouldShow(
                contentOffsetY: 44,
                isNearBottom: false,
                isSearchMode: false
            )
        )
        XCTAssertTrue(
            ChatScrollDownButtonVisibilityPolicy.shouldShow(
                contentOffsetY: 44.01,
                isNearBottom: false,
                isSearchMode: false
            )
        )
        XCTAssertFalse(
            ChatScrollDownButtonVisibilityPolicy.shouldShow(
                contentOffsetY: 60,
                isNearBottom: true,
                isSearchMode: false
            )
        )
        XCTAssertFalse(
            ChatScrollDownButtonVisibilityPolicy.shouldShow(
                contentOffsetY: 60,
                isNearBottom: false,
                isSearchMode: true
            )
        )
    }

    func testTargetPolicyUsesUnreadBoundaryWhenBoundaryIsNewerThanVisibleRealMessages() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(syncUnreadAfterId: "300"),
            visibleMessages: [
                visibleMessage(archivedId: "100"),
                visibleMessage(archivedId: "299")
            ]
        )

        XCTAssertEqual(target, .unreadBoundary("300"))
    }

    func testTargetPolicyFallsBackToLatestWhenBoundaryIsOlderOrEqualToVisibleRealMessage() {
        XCTAssertEqual(
            ChatScrollDownTargetPolicy.target(
                chat: chatState(syncUnreadAfterId: "300"),
                visibleMessages: [visibleMessage(archivedId: "300")]
            ),
            .latest
        )
        XCTAssertEqual(
            ChatScrollDownTargetPolicy.target(
                chat: chatState(syncUnreadAfterId: "300"),
                visibleMessages: [visibleMessage(archivedId: "301")]
            ),
            .latest
        )
    }

    func testTargetPolicyFallsBackToLatestWhenUnreadIsZero() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(unread: 0, syncUnreadAfterId: "300"),
            visibleMessages: []
        )

        XCTAssertEqual(target, .latest)
    }

    func testTargetPolicyFallsBackToLatestForInvalidBoundary() {
        let invalidBoundaries: [String?] = [nil, "", "   ", "abc", "0", "-1"]

        for boundary in invalidBoundaries {
            XCTAssertEqual(
                ChatScrollDownTargetPolicy.target(
                    chat: chatState(syncUnreadAfterId: boundary, lastReadId: nil),
                    visibleMessages: []
                ),
                .latest,
                "Boundary \(String(describing: boundary)) should not target unread"
            )
        }
    }

    func testTargetPolicyFallsBackToLastReadIdWhenSyncUnreadAfterIdIsMissing() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(syncUnreadAfterId: nil, lastReadId: "300"),
            visibleMessages: [visibleMessage(archivedId: "100")]
        )

        XCTAssertEqual(target, .unreadBoundary("300"))
    }

    func testTargetPolicyIgnoresFakeAndNonMessageVisibleRows() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(syncUnreadAfterId: "300"),
            visibleMessages: [
                visibleMessage(archivedId: "999", rowKind: .message, isFakeMessage: true),
                visibleMessage(archivedId: "999", rowKind: .date),
                visibleMessage(archivedId: "999", rowKind: .unread),
                visibleMessage(archivedId: "999", rowKind: .initial),
                visibleMessage(archivedId: "999", rowKind: .skeleton),
                visibleMessage(archivedId: "299", rowKind: .message)
            ]
        )

        XCTAssertEqual(target, .unreadBoundary("300"))
    }

    func testTargetPolicyUsesUnreadWhenNoVisibleRealMessagesAndBoundaryIsValid() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(syncUnreadAfterId: "300"),
            visibleMessages: [
                visibleMessage(archivedId: "999", rowKind: .date),
                visibleMessage(archivedId: "999", rowKind: .skeleton)
            ]
        )

        XCTAssertEqual(target, .unreadBoundary("300"))
    }

    func testTargetPolicyFallsBackToLatestWhenVisibleRealMessageHasNonNumericArchiveId() {
        let target = ChatScrollDownTargetPolicy.target(
            chat: chatState(syncUnreadAfterId: "300"),
            visibleMessages: [visibleMessage(archivedId: "not-a-number")]
        )

        XCTAssertEqual(target, .latest)
    }

    func testLayoutPolicyAlignsScrollButtonWithSendButtonAndTracksMovement() throws {
        let sendFrame = CGRect(x: 318, y: 700, width: 44, height: 44)
        let frame = try XCTUnwrap(
            ChatViewController.FloatingControlsLayoutPolicy.scrollButtonVisibleFrame(
                sendButtonFrame: sendFrame
            )
        )

        XCTAssertEqual(frame.size, CGSize(square: NativeGlassBarStyle.buttonSize))
        XCTAssertEqual(frame.midX, sendFrame.midX, accuracy: 0.001)
        XCTAssertEqual(
            frame.maxY,
            sendFrame.minY - NativeGlassBarStyle.interItemSpacing,
            accuracy: 0.001
        )

        let movedSendFrame = sendFrame.offsetBy(dx: -12, dy: -260)
        let movedFrame = try XCTUnwrap(
            ChatViewController.FloatingControlsLayoutPolicy.scrollButtonVisibleFrame(
                sendButtonFrame: movedSendFrame
            )
        )

        XCTAssertEqual(movedFrame.origin.x - frame.origin.x, -12, accuracy: 0.001)
        XCTAssertEqual(movedFrame.origin.y - frame.origin.y, -260, accuracy: 0.001)
    }

    func testLayoutPolicyReturnsNilForInvalidSendButtonFrame() {
        XCTAssertNil(
            ChatViewController.FloatingControlsLayoutPolicy.scrollButtonVisibleFrame(
                sendButtonFrame: .zero
            )
        )
    }
}

final class ChatUnreadMentionsTests: XCTestCase {

    private let owner = "owner@example.com"
    private let groupchatJid = "trio@example.com"
    private let currentMemberId = "me-1"

    override func setUpWithError() throws {
        let realm = try WRealm.safe()
        try realm.write {
            realm.objects(MessageStorageItem.self)
                .filter("owner == %@", owner)
                .forEach { realm.delete($0) }
            realm.objects(NotificationStorageItem.self)
                .filter("owner == %@", owner)
                .forEach { realm.delete($0) }
            realm.objects(LastChatsStorageItem.self)
                .filter("owner == %@", owner)
                .forEach { realm.delete($0) }
            realm.objects(GroupchatUserStorageItem.self)
                .filter("owner == %@", owner)
                .forEach { realm.delete($0) }
        }
    }

    private func insertLastChat(
        jid: String? = nil,
        conversationType: ClientSynchronizationManager.ConversationType = .group
    ) throws {
        let jid = jid ?? groupchatJid
        let realm = try WRealm.safe()
        let chat = LastChatsStorageItem()
        chat.owner = owner
        chat.jid = jid
        chat.conversationType = conversationType
        chat.primary = LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: conversationType)
        chat.groupchatMyId = currentMemberId

        try realm.write {
            realm.add(chat, update: .modified)
        }
    }

    private func insertMyGroupUser(
        jid: String? = nil,
        userId: String? = nil,
        isHidden: Bool = false
    ) throws {
        let jid = jid ?? groupchatJid
        let userId = userId ?? currentMemberId
        let realm = try WRealm.safe()
        let member = GroupchatUserStorageItem()
        member.owner = owner
        member.userId = userId
        member.jid = owner
        member.groupchatId = [jid, owner].prp()
        member.primary = GroupchatUserStorageItem.genPrimary(id: userId, groupchat: jid, owner: owner)
        member.isMe = true
        member.isHidden = isHidden

        try realm.write {
            realm.add(member, update: .modified)
        }
    }

    private func makeReference(
        kind: MessageReferenceStorageItem.Kind,
        metadata: [String: Any]
    ) -> MessageReferenceStorageItem {
        let reference = MessageReferenceStorageItem()
        reference.kind = kind
        reference.metadata = metadata
        return reference
    }

    private func makeMessage(
        primary: String,
        archivedId: String,
        messageId: String = "",
        authorId: String,
        isRead: Bool = false,
        isDeleted: Bool = false,
        mentionMemberIds: [String] = [],
        date: Date
    ) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = primary
        message.archivedId = archivedId
        message.owner = owner
        message.opponent = groupchatJid
        message.body = mentionMemberIds.isEmpty ? "Hello" : "Hello @you"
        message.displayAs = .text
        message.conversationType = .group
        message.isRead = isRead
        message.isDeleted = isDeleted
        message.outgoing = false
        message.messageId = messageId
        message.date = date
        message.sentDate = date

        let authorReference = makeReference(
            kind: .groupchat,
            metadata: [
                "id": authorId,
                "nickname": "Author \(authorId)"
            ]
        )
        message.references.append(authorReference)

        mentionMemberIds.forEach { memberId in
            let mentionReference = makeReference(
                kind: .mention,
                metadata: [
                    "uri": "xmpp:\(groupchatJid)?members;id=\(memberId)",
                    "memberId": memberId,
                    "groupchatJid": groupchatJid,
                    "nickname": "@\(memberId)"
                ]
            )
            message.references.append(mentionReference)
        }

        return message
    }

    private func makeMentionNotification(
        primary: String,
        archivedId: String? = nil,
        messageId: String? = nil,
        authorId: String = "other-1",
        targetMemberId: String? = nil,
        isRead: Bool = false,
        linkStatus: NotificationStorageItem.MentionLinkStatus? = .resolved,
        conversationType: ClientSynchronizationManager.ConversationType? = .group,
        sourceChatJid: String? = nil,
        date: Date
    ) -> NotificationStorageItem {
        let notification = NotificationStorageItem()
        notification.primary = primary
        notification.owner = owner
        notification.category = .mention
        notification.isRead = isRead
        notification.sourceConversationType = conversationType
        notification.sourceChatJid = sourceChatJid ?? groupchatJid
        notification.sourceArchivedId = archivedId
        notification.sourceMessageId = messageId
        notification.sourceSenderId = authorId
        notification.mentionTargetUserId = targetMemberId ?? currentMemberId
        notification.sourceMessageDate = date
        notification.mentionLinkStatus = linkStatus
        return notification
    }

    func testUnreadMentionMatcherUsesUnreadNotificationStateInsteadOfMessageReadState() throws {
        let message = makeMessage(
            primary: "m1",
            archivedId: "a1",
            messageId: "mid-1",
            authorId: "other-1",
            isRead: true,
            mentionMemberIds: [currentMemberId],
            date: Date(timeIntervalSince1970: 10)
        )
        let notification = makeMentionNotification(
            primary: "n1",
            archivedId: "a1",
            messageId: "mid-1",
            date: Date(timeIntervalSince1970: 10)
        )
        let realm = try WRealm.safe()

        try realm.write {
            realm.add(message, update: .modified)
            realm.add(notification, update: .modified)
        }

        let messages = realm.objects(MessageStorageItem.self)
            .filter("owner == %@ AND opponent == %@", owner, groupchatJid)

        let item = ChatUnreadMentionMatcher.unreadMentionItem(
            from: notification,
            messagesObserver: messages,
            observerLookupMaps: ChatObserverLookupPolicy.build(from: messages),
            in: realm,
            chatPrimary: "chat-1",
            currentMemberId: currentMemberId,
            groupchatJid: groupchatJid
        )

        XCTAssertEqual(item?.notificationPrimary, "n1")
        XCTAssertEqual(item?.messagePrimary, "m1")
        XCTAssertEqual(item?.archivedId, "a1")
        XCTAssertEqual(item?.targetMemberId, currentMemberId)
        XCTAssertEqual(item?.groupchatJid, groupchatJid)
        XCTAssertTrue(
            ChatUnreadMentionFloatingControlPolicy.shouldShowNavigator(
                conversationType: .group,
                unreadCount: item == nil ? 0 : 1,
                isSearchMode: false
            )
        )
    }

    func testCurrentGroupMemberIdUsesCompositeGroupchatStorageKey() throws {
        try insertMyGroupUser()
        let realm = try WRealm.safe()

        XCTAssertEqual(
            MentionNotificationSync.currentGroupMemberId(
                owner: owner,
                groupchatJid: groupchatJid,
                in: realm
